/** One story on the storyline stack: what was asked for, and what came back. */
interface StorylineStep {
  request: { file?: string; partRef?: string }
  /** What the crumb calls it: the file's name, or the part's. */
  label: string
  /** A chip's landing: the called piece's name, found by name when the answer lands. */
  startAt: string | null
  answer: StorylineAnswer | null
  /** The entry the reader is on — kept when they come Back to this story. */
  entry: string | null
  /**
   * Whether this step's refusal already opened the peek. Only its FIRST show
   * does: Back or a crumb re-showing it must not re-open a drawer the reader
   * closed.
   */
  peeked?: boolean
}

interface StorylineLevel {
  rootId: string
  stack: StorylineStep[]
  /** Where the story was opened, as crumbs: each name and the depth it pops to. */
  origin: Array<{ name: string; depth: number | null }>
  types: boolean
  /**
   * The plan whose Today ⇄ After the story carries (story-today-after) — set
   * when the story is opened from a plan's review, and kept for every file a
   * chip leads to from there. Null outside a plan: the story is unchanged.
   */
  plan: string | null
  /** Today or After, while the answer carries a comparison. After opens. */
  time: StoryTime
  /**
   * The plan change review this story was opened for (plan
   * `plan_change_review`) — drawn on the first story of the stack only; a
   * chip into another file from there reads that file as a plain story.
   */
  review: PlanReviewSession | null
  /** Today, Proposal or Verify, while a review is open. Proposal opens. */
  mode: ReviewMode
}
