/** Inset kept around the graph when fitting it into the viewport. */
const FIT_PADDING = 56

/**
 * PUT A RECTANGLE WHERE ITS RENDER PLAN SAYS.
 *
 * Every cell, country, ghost province and lens is absolutely positioned from a
 * `Rect` in STAGE coordinates — `territory-view` already accounted for the
 * title strip and the foot, so the sheet layer is simply `inset: 0` and a
 * rectangle needs no second transform to land where it was computed. Two
 * decimals, so a 1030px sheet divides without a sub-pixel seam opening between
 * neighbours.
 */
/** One plain sentence for links that could not be read — no file names, no codes. */
const WS_LINKS_UNREADABLE = CONNECTIONS_UNREADABLE

/** Where the Connections choice is remembered — this viewer's own preference. */
const WS_CONNECTIONS_PREF = 'flow.blueprint.workspace.connections'

function readWorkspaceConnectionsPref(): boolean {
  try {
    return window.localStorage.getItem(WS_CONNECTIONS_PREF) === 'on'
  } catch {
    return false // storage refused — off, the default
  }
}

function writeWorkspaceConnectionsPref(on: boolean): void {
  try {
    window.localStorage.setItem(WS_CONNECTIONS_PREF, on ? 'on' : 'off')
  } catch {
    // storage refused — the choice holds for this session only
  }
}

/** Where a plan review's unsent comments are kept — this viewer's storage, or none when it is refused. */
function reviewDraftStorage(): import('./note-review-model').DraftStorage | null {
  try {
    return window.localStorage
  } catch (error) {
    console.warn('flow: no storage for review comments — they last until the board closes', error)
    return null
  }
}

/** An SVG element with its attributes. */
function svgEl(name: string, attributes: Record<string, string>): SVGElement {
  const el = document.createElementNS('http://www.w3.org/2000/svg', name)
  for (const [key, value] of Object.entries(attributes)) el.setAttribute(key, value)
  return el
}

/** An outline folder — the file tree's own mark, drawn small for a folder row. */
function folderGlyph(): SVGElement {
  const icon = svgEl('svg', { viewBox: '0 0 12 10', width: '11', height: '9', class: 'fb-terr-folder-glyph', 'aria-hidden': 'true' })
  icon.appendChild(
    svgEl('path', {
      d: 'M1 2.2V8.6c0 .3.2.4.4.4h9.2c.2 0 .4-.1.4-.4V3.4c0-.3-.2-.4-.4-.4H5.6L4.5 1.6c-.1-.1-.2-.1-.3-.1H1.4c-.2 0-.4.2-.4.7z',
      fill: 'none',
      stroke: 'currentColor',
      'stroke-width': '1',
      'stroke-linejoin': 'round',
    }),
  )
  return icon
}

/** A pin — a home a person chose, not one the map worked out. */
function pinGlyph(): SVGElement {
  const icon = svgEl('svg', { viewBox: '0 0 10 10', width: '9', height: '9', class: 'fb-terr-folder-pin', role: 'img', 'aria-label': 'chosen as the home' })
  icon.appendChild(
    svgEl('path', {
      d: 'M3.4 1h3.2M4 1.2v2.6L2.4 5.6h5.2L6 3.8V1.2M5 5.6V9',
      fill: 'none',
      stroke: 'currentColor',
      'stroke-width': '1.1',
      'stroke-linecap': 'round',
      'stroke-linejoin': 'round',
    }),
  )
  return icon
}

function placeRect(el: HTMLElement, rect: TerritoryRect): void {
  el.style.left = `${rect.x.toFixed(2)}px`
  el.style.top = `${rect.y.toFixed(2)}px`
  el.style.width = `${rect.w.toFixed(2)}px`
  el.style.height = `${rect.h.toFixed(2)}px`
}

/**
 * The open-level control's mark: two cards and the edge between them — a small
 * FLOW DIAGRAM, because a feature view is what it opens. Drawing the
 * destination rather than an arrow is what stops it reading as "expand".
 *
 * The card height (3.0) against the connector's stroke (0.7, in the CSS) is the
 * ratio that does the work: at 2.6 against 0.95 the three parts weighed the
 * same and the crop showed one continuous zigzag ribbon. Cards and edge have to
 * be different KINDS of mark, not just different shapes, or 14px renders them
 * as a single squiggle. (Measured on the ring's SVG control; the geometry is
 * carried over verbatim into an 18 × 14 viewBox.)
 */
function openGlyphMark(): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg')
  svg.setAttribute('class', 'fb-terr-control-mark')
  svg.setAttribute('viewBox', '0 0 18 14')
  svg.setAttribute('aria-hidden', 'true')
  const CARD_W = 6.2
  const CARD_H = 4.2
  const cards: readonly [number, number][] = [
    [2.0, 1.4],
    [9.8, 8.4],
  ]
  const edge = document.createElementNS(SVG_NS, 'line')
  edge.setAttribute('class', 'fb-terr-control-edge')
  edge.setAttribute('x1', String(cards[0][0] + CARD_W / 2))
  edge.setAttribute('y1', String(cards[0][1] + CARD_H))
  edge.setAttribute('x2', String(cards[1][0] + CARD_W / 2))
  edge.setAttribute('y2', String(cards[1][1]))
  svg.appendChild(edge)
  for (const [x, y] of cards) {
    const card = document.createElementNS(SVG_NS, 'rect')
    card.setAttribute('class', 'fb-terr-control-node')
    card.setAttribute('x', String(x))
    card.setAttribute('y', String(y))
    card.setAttribute('width', String(CARD_W))
    card.setAttribute('height', String(CARD_H))
    card.setAttribute('rx', '1')
    svg.appendChild(card)
  }
  return svg
}

/**
 * The corpus-browser control's mark: a three-line LIST (#1532) — a filterable
 * list of docs is what it opens, the same "draw the destination" rule. The
 * lines are STAGGERED: same length and they read as a hamburger menu, which
 * promises navigation this control does not do.
 */
/**
 * The Learn control's mark: the BRAIN, the same glyph the header's Learn button
 * and the Learning panel already use.
 *
 * A book-and-spark was the first cut and it read as neither — at 18x14 the
 * spine and the spark blur into one shape, and "book" is not this app's word
 * for what a pass does anyway. Learning has ONE picture in this product; a
 * second one for the same verb is a second vocabulary.
 *
 * The path is `fl-icon`'s `brain`, in its own 16-unit box, translated into this
 * button's 18x14 frame. Copied rather than mounting the component: these marks
 * live inside an absolutely-positioned 18x14 button on a cell corner, and the
 * icon component brings its own sizing box that does not fit there.
 */
function learnGlyphMark(): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg')
  svg.setAttribute('class', 'fb-terr-control-mark')
  svg.setAttribute('viewBox', '0 0 16 16')
  svg.setAttribute('aria-hidden', 'true')
  const brain = document.createElementNS(SVG_NS, 'path')
  brain.setAttribute('class', 'fb-terr-control-node')
  brain.setAttribute(
    'd',
    'M8 3.2 C7.2 2 5.2 2 4.4 3.2 C3 3.3 2.2 4.8 2.8 6 C1.9 7 2.2 8.8 3.4 9.4 C3.4 11 5 12 6.5 11.4 L8 12.8 M8 3.2 C8.8 2 10.8 2 11.6 3.2 C13 3.3 13.8 4.8 13.2 6 C14.1 7 13.8 8.8 12.6 9.4 C12.6 11 11 12 9.5 11.4 L8 12.8 M8 3.2 V12.8',
  )
  svg.appendChild(brain)
  return svg
}

function corpusGlyphMark(): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg')
  svg.setAttribute('class', 'fb-terr-control-mark')
  svg.setAttribute('viewBox', '0 0 18 14')
  svg.setAttribute('aria-hidden', 'true')
  const rows: readonly [number, number][] = [
    [2.4, 3.2],
    [2.4, 7.0],
    [2.4, 10.8],
  ]
  const widths = [13.2, 10.0, 11.6]
  rows.forEach(([x, y], index) => {
    const line = document.createElementNS(SVG_NS, 'line')
    line.setAttribute('class', 'fb-terr-control-edge')
    line.setAttribute('x1', String(x))
    line.setAttribute('y1', String(y))
    line.setAttribute('x2', String(x + widths[index]))
    line.setAttribute('y2', String(y))
    svg.appendChild(line)
  })
  return svg
}

/** True when the event target is a text-entry field (so `0` doesn't hijack typing). */
function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false
  const tag = target.tagName
  return tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable
}

